// THE PLANNING METRICS — one definition each (planning review, Phase 4 / PC1; docs/planning-review/04-metric-specification.md).
// ONE source for three readers: the dictionary pages (metricDictionary.js → dictionaryDirectory.js → /settings/metrics), the formula groups of dictionaryDocs.js («المستهدفات والتخطيط»)
// and the handover documents. Every entry carries: business definition, formula, unit, aggregation level, date basis, source fields, missing / zero handling and the owner function —
// in Arabic and English. No number is calculated here; the formulas are the ones implemented in src/data/plans/planBasis.js, planMeasures.js and src/data/planForecast.js (named in `where`).
// Owners are the SUGGESTED functions of docs/planning-review/10-open-decisions.md: they are to be confirmed by the business, not decided here.
const BI = (ar, en) => ({ ar, en });
const OWN_FIN = BI('الإدارة المالية (صاحبة المستهدف والخطة) — مقترح، يُؤكَّد', 'Finance (owner of the target and the plan) — suggested, to be confirmed');
const OWN_DATA = BI('مالك بيانات التحصيل (مصدر «تحصيل») — مقترح، يُؤكَّد', 'Collection data owner (the Tahseel source) — suggested, to be confirmed');
const OWN_PLAN = BI('إدارة تخطيط الإيرادات (مالك طريقة الحساب) — مقترح، يُؤكَّد', 'Revenue planning (owner of the calculation method) — suggested, to be confirmed');
const OWN_COLL = BI('إدارة التحصيل (مالك قواعد الإجراء) — مقترح، يُؤكَّد', 'Collection management (owner of the action rules) — suggested, to be confirmed');
const SAR = BI('ريال سعودي (يُعرض بالمليار/المليون)', 'Saudi riyals (shown in billions / millions)');
const PCT = BI('نسبة مئوية (كسر ×100، دون سقف 100%)', 'Percentage (a fraction ×100, not capped at 100%)');
const FY = BI('العام المالي (1 يناير – 31 ديسمبر) حتى تاريخ التقرير', 'Fiscal year (1 January – 31 December) up to the reporting date');
const ASOF = BI('تاريخ التقرير = الأصغر بين اليوم وآخر تاريخ بيانات (في العرض: اليوم)', 'Reporting date = the earlier of today and the latest data date (in the demo: today)');
const SUMMED = BI('تُحسب النسب على المجاميع (مجموع البسط ÷ مجموع المقام) ولا تُتوسَّط نسب الجهات', 'Ratios are computed from sums (Σ numerator ÷ Σ denominator); entity percentages are never averaged');

const BASE = [
  { key: 'annualTarget', label: BI('مستهدف الخطة', 'Plan target'), sources: ['tahseel'],
    brief: BI('المبلغ المطلوب تحصيله خلال فترة الخطة، يُدخله صاحب الخطة بالريال؛ الجهات والبلديات توزَّع منه من الأعلى إلى الأسفل.', 'The amount to be collected during the plan period, typed by the plan owner in riyals; entities and municipalities are allocated from it top-down.'),
    definition: BI('رقم واحد لكل خطة مسمّاة: مستهدف الفترة كاملة. لا يُحسب تلقائيًا من الميزانية؛ أداة «الميزانية × التغطية» تقترح مبلغًا فقط ويُحفظ أساس الاقتراح ملاحظة. تغيير المستهدف لا يعدّل صفوف التخصيص؛ والفرق بين مجموع الصفوف والمستهدف يظهر «غير موزَّع» أو «زيادة» ويمنع الحفظ حتى يُوزَّع صراحةً. لا تُجمع مستهدفات خطط مختلفة في أي رقم.', 'One number per named plan: the target of the whole period. It is not derived automatically from the budget; the «budget × coverage» aid only suggests an amount and the basis of the suggestion is kept as a note. Changing the target never edits the allocation rows; the difference between the rows and the target shows as «unallocated» or «excess» and blocks saving until it is distributed explicitly. The targets of different plans are never added into any figure.'),
    formula: BI('المستهدف = المبلغ المُدخل للفترة؛ ويجب أن يساوي مجموع صفوف التخصيص إلى الريال عند الحفظ', 'Target = the amount typed for the period; the allocation rows must add up to it to the riyal when saving'),
    f: 'T = plan.target.amount;   save requires  Σ allocations = T',
    inputs: [[BI('المبلغ المُدخل', 'The typed amount'), BI('ريالات صحيحة', 'Whole riyals')], [BI('صفوف التخصيص', 'Allocation rows'), BI('جهات، ثم بلديات اختياريًا', 'Entities, then municipalities optionally')]],
    steps: [BI('أدخل المستهدف بوحدة المنصة (المبلغ الدقيق بالريال في التلميح).', 'Enter the target in the platform unit (the exact riyals in the tooltip).'), BI('وزّع المتبقي بمعاينة قبل/بعد تُظهر باقي التقريب.', 'Distribute the remainder through a before/after preview that shows the rounding remainder.')],
    unit: SAR, level: BI('الخطة ثم الجهة ثم البلدية (اختياري)؛ قابل للجمع داخل الخطة الواحدة فقط', 'Plan, then entity, then municipality (optional); additive within one plan only'),
    period: BI('فترة الخطة (السنة يناير–ديسمبر افتراض بانتظار تأكيد الجهة المعنية، أو نطاق تواريخ)', 'The plan period (the January–December year is an assumption pending business confirmation, or a date range)'), dateBasis: BI('لا يتأثر بتاريخ التقرير', 'Independent of the reporting date'),
    sourceFields: BI('محتوى الخطة المحفوظة: المستهدف والتخصيص (خدمة البيانات)', 'The saved plan content: the target and the allocation (the data service)'),
    missing: BI('لا مستهدف أو صفر ← «لا مستهدف»: لا نسبة ولا انحراف ولا فجوة، والتحصيل الصفري ليس نجاحًا. بلدية بلا تخصيص ← «لم يُحدد مستهدف لهذه البلدية» (لا يُستعمل مستهدف الأمانة ولا يُقسَّم).', 'No target or zero → «no target»: no percentage, deviation or gap, and zero collection is not a success. A municipality with no allocation → «no target has been set for this municipality» (the Amanah target is neither reused nor divided).'),
    owner: OWN_FIN, where: 'planBasis.js · planningBasisFromPlan().target; planRules.js · allocationSummary()',
    notes: [BI('المحاسبة الجارية: مستهدف الخطة ليس قرارًا رسميًا بالمستهدف؛ الخطة الافتراضية للنظام توضيحية.', 'A plan target is not an official decision on the target; the system default plan is illustrative.')] },

  { key: 'actualToDate', label: BI('المحصَّل الفعلي حتى تاريخه', 'Actual collected to date'), sources: ['tahseel', 'sadad'],
    brief: BI('مجموع المدفوعات بتاريخ الدفع من 1 يناير حتى تاريخ التقرير.', 'Σ payments by payment date from 1 January to the reporting date.'),
    definition: BI('ما حُصِّل فعليًا في العام المالي حتى تاريخ التقرير، على أي فاتورة (مدفوعات «تحصيل» بتاريخ الدفع)، بقواعد الاستبعاد المعتمدة فقط وفي الفئات الرئيسية للإيراد (ما عداها «أخرى» خارج الإجمالي). هو أساس المقارنة بالمستهدف والخطة، وهو غير «المحصّل» على فواتير الفترة في صفحات الفواتير ويُعرض الجسر بينهما.', 'What was actually collected in the fiscal year up to the reporting date, on any invoice (Tahseel payments by payment date), under the approved exclusion rules only and in the main revenue classes («Other» is outside the gross). It is the basis of every comparison with the target and the plan, and it is not «collected» on the period’s invoices on the invoice pages; the bridge between the two is shown.'),
    formula: BI('Σ المدفوعات بتاريخ دفع ∈ [1 يناير، تاريخ التقرير]', 'Σ payments with payment date ∈ [1 Jan, reporting date]'),
    f: 'C(asOf) = Σ payments with payDate in [1 Jan, asOf]',
    inputs: [[BI('المدفوعات', 'Payments'), BI('مبلغ وتاريخ دفع كل دفعة', 'The amount and payment date of each payment')]],
    steps: [BI('اختر المدفوعات بتاريخ دفع ضمن العام المالي حتى تاريخ التقرير.', 'Select the payments dated within the fiscal year up to the reporting date.'), BI('طبّق قواعد الاستبعاد المعتمدة والفئات الرئيسية.', 'Apply the approved exclusion rules and the main classes.'), BI('اجمع حسب الشهر والجهة؛ المجموع الشهري = مجموع الجهات = المجموع الكلي.', 'Sum by month and entity; the monthly total = the sum of the entities = the grand total.')],
    unit: SAR, level: BI('الدفعة ← الشهر × الجهة ← إجمالي النطاق؛ قابل للجمع', 'Payment → month × entity → scope total; additive'),
    period: FY, dateBasis: BI('تاريخ الدفع', 'Payment date'),
    sourceFields: BI('مدفوعات «تحصيل»: تاريخ الدفع، مبلغ الدفعة، الجهة، فئة الإيراد، حالة الاستبعاد', 'Tahseel payments: payment date, payment amount, entity, revenue class, exclusion status'),
    missing: BI('الأشهر بعد تاريخ التقرير = غير متاحة (null) وليست صفرًا؛ لا بيانات = «غير متاح».', 'Months after the reporting date are missing (null), never 0; no data = «not available».'),
    owner: OWN_DATA, where: 'server/engine.js · series() / snapshot().receivedInPeriod; planBasis.js · actualToDate',
    notes: [BI('حد معروف: الدفعات على فواتير ذات قناع استبعاد تُحتسب في السلسلة الشهرية ولا تدخل في بعض مؤشرات الفترة؛ التطابق قائم اليوم ويُوثَّق في سجل الاستثناءات.', 'Known limit: payments on invoices carrying an exclusion mask are in the monthly series and not in some period indicators; they agree today and the case is recorded in the findings register.')] },

  { key: 'plannedToDate', label: BI('المخطط حتى تاريخه', 'Planned to date'), sources: ['tahseel'],
    brief: BI('الجزء من المستهدف المخطط تحصيله حتى تاريخ الإغلاق وفق التوزيع الشهري للخطة.', 'The part of the target planned for collection by the cut-off, by the plan\'s monthly distribution.'),
    definition: BI('تراكمي الخطة حتى تاريخ الإغلاق: الأشهر المنقضية كاملة + حصة شهر الإغلاق بنسبة أيامه المنقضية. التوزيع الشهري صريح دائمًا: «متساوٍ» (افتراض يُكتب بجانب الرقم) أو «يدوي» بنسب أساس نقطة تساوي 10 000 بالضبط. الشهر الجزئي في أول الفترة أو آخرها يُوزن بكسر أيامه. لا تُعاد معايرة النسب بصمت.', 'The cumulative plan to the cut-off: the closed months in full + the cut-off month by its elapsed days. The monthly distribution is always explicit: «equal» (an assumption, printed beside the figure) or «manual» in basis points that add up to exactly 10,000. A partial first or last month is weighted by its day fraction. Weights are never rescaled silently.'),
    formula: BI('المخطط = تراكمي الأشهر المغلقة + (مبلغ شهر الإغلاق × أيامه المنقضية ÷ أيام الشهر)', 'Planned = the cumulative of the closed months + (the cut-off month amount × its elapsed days ÷ the month days)'),
    f: 'P(cutoff) = Σ_{closed months} plan[m] + plan[cutoffMonth] * elapsedDays / monthDays',
    inputs: [[BI('المستهدف والتخصيص', 'Target and allocation'), BI('انظر مستهدف الخطة', 'See the plan target')], [BI('التوزيع الشهري', 'Monthly distribution'), BI('متساوٍ (افتراض) أو يدوي بنقاط الأساس', 'Equal (an assumption) or manual in basis points')]],
    steps: [BI('وزّع مبلغ كل صف على أشهر الفترة بأكبر باقٍ (المجموع دقيق بالريال).', 'Apportion each row\'s amount over the period months by largest remainder (the sum is exact to the riyal).'), BI('اجمع الأشهر المغلقة وحصة شهر الإغلاق بالأيام.', 'Add the closed months and the cut-off month by days.')],
    unit: SAR, level: BI('الخطة ثم الجهة ثم البلدية؛ قابل للجمع داخل الخطة: مجموع المخطط للصفوف = مخطط الخطة', 'Plan, then entity, then municipality; additive within the plan: Σ row planned = plan planned'),
    period: BI('من بداية فترة الخطة حتى تاريخ الإغلاق', 'From the plan period start to the cut-off'), dateBasis: BI('الشهر التقويمي مع تناسب الأيام (اتفاقية موثّقة وليست دليلًا)', 'Calendar month with day proration (a documented convention, not evidence)'),
    sourceFields: BI('محتوى الخطة المحفوظة: المستهدف والتخصيص والتوزيع الشهري', 'The saved plan content: target, allocation and monthly distribution'),
    missing: BI('لا مستهدف أو لا توزيع شهري محدد ← لا مخطط ولا انحراف؛ فترة لم تبدأ ← لا مخطط. بلدية بلا تخصيص ← لا مخطط (غير متاح).', 'No target or no monthly distribution chosen → no planned figure or deviation; a period that has not started → no planned figure. A municipality with no allocation → no planned figure (not available).'),
    owner: OWN_FIN, where: 'planMath.js · plannedTo() / monthAmounts(); planBasis.js · plannedToDate',
    notes: [BI('التوزيع المتساوي افتراض ظاهر لا موسمية مستنتجة؛ يُستبدل بتوزيع يدوي تؤكده الإدارة المالية.', 'The equal distribution is a visible assumption, not an inferred seasonality; it is replaced by a manual distribution confirmed by Finance.')] },

  { key: 'planDeviation', label: BI('الانحراف عن المخطط حتى تاريخه', 'Deviation from the plan to date'), sources: ['tahseel'],
    brief: BI('المحصَّل − المخطط حتى تاريخه بمبلغ موقّع؛ بلا تصنيف لفظي للحالة.', 'Collected − planned to date as a signed amount; no status label.'),
    definition: BI('الفرق النقدي الموقّع بين ما حُصِّل وما كان مخططًا حتى تاريخ الإغلاق. الموجب فوق المخطط والسالب دونه، ودون شارة حالة. تُعرض معه «نسبة الإنجاز مقابل المخطط»؛ أما الانحراف النسبي (÷ المخطط) فيظهر في تلميح أو تفصيل أو تصدير فقط وليس رقمًا رئيسيًا.', 'The signed monetary difference between what was collected and what was planned by the cut-off. Positive is above the plan, negative below it, with no status badge. It is shown with «achievement against plan»; the relative deviation (÷ planned) appears only in a tooltip, a detail or an export, never as a headline number.'),
    formula: BI('الانحراف = المحصَّل حتى تاريخه − المخطط حتى تاريخه', 'Deviation = actual to date − planned to date'),
    f: 'dev = C(cutoff) - P(cutoff);   devPct = dev / P(cutoff)  (tooltip only)',
    inputs: [[BI('المحصَّل الفعلي حتى تاريخه', 'Actual to date'), BI('انظر تعريفه', 'See its definition')], [BI('المخطط حتى تاريخه', 'Planned to date'), BI('انظر تعريفه', 'See its definition')]],
    steps: [BI('احسب المحصَّل والمخطط لنفس الصف وتاريخ الإغلاق.', 'Compute actual and planned for the same row and cut-off.'), BI('اطرح المخطط من المحصَّل واحتفظ بالإشارة.', 'Subtract planned from actual and keep the sign.')],
    unit: SAR, level: BI('الخطة ثم الجهة ثم البلدية؛ قابل للجمع (مجموع الصفوف مع «أخرى» = انحراف الخطة)', 'Plan, then entity, then municipality; additive (the rows with «other» add up to the plan deviation)'), period: BI('من بداية فترة الخطة حتى تاريخ الإغلاق', 'From the plan period start to the cut-off'), dateBasis: BI('تاريخ الإغلاق', 'The cut-off date'),
    sourceFields: BI('المحصَّل الفعلي حتى تاريخه + المخطط حتى تاريخه', 'Actual to date + planned to date'),
    missing: BI('لا مستهدف أو لا مخطط أو لا بيانات فعلية ← «غير متاح» مع السبب، وليس صفرًا.', 'No target, no planned figure or no actual data → «not available» with the reason, never zero.'),
    owner: OWN_PLAN, where: 'planBasis.js · deviationAmount(); planMeasures.js · deviation',
    notes: [BI('الإشارة والمبلغ هما القراءة؛ لا تصنيف لفظيًا.', 'The sign and the amount are the reading; there is no verbal label.')] },

  { key: 'planAchievement', label: BI('نسبة تحقيق المستهدف حتى تاريخه', 'Target achievement to date'), sources: ['tahseel'],
    brief: BI('المحصَّل الفعلي حتى تاريخه ÷ مستهدف الفترة كاملة؛ دون سقف 100%.', 'Actual to date ÷ the full-period target; not capped at 100 %.'),
    definition: BI('كم بلغ التحصيل من مستهدف الفترة كاملة حتى تاريخ الإغلاق. تختلف عن «نسبة الإنجاز مقابل المخطط» (المقام المخطط حتى تاريخه) وعن «نسبة تحقيق المستهدف المتوقعة بنهاية الفترة» (البسط التوقع) وعن نسبة التحصيل (المحصّل ÷ صافي المفوتر) وعن التغطية (المحصّل ÷ الميزانية): نسب لا يُستبدل بعضها ببعض.', 'How much of the whole-period target has been collected by the cut-off. It differs from «achievement against plan» (the denominator is planned to date), from «expected target achievement by the end of the period» (the numerator is the forecast), from the collection rate (collected ÷ net billed) and from coverage (collected ÷ budget): percentages that are never interchanged.'),
    formula: BI('نسبة تحقيق المستهدف حتى تاريخه = المحصَّل حتى تاريخه ÷ مستهدف الفترة كاملة × 100', 'Target achievement to date = actual to date ÷ the full-period target × 100'),
    f: 'achievementToDate = C(cutoff) / T * 100  when T > 0  (not capped)',
    inputs: [[BI('المحصَّل الفعلي حتى تاريخه', 'Actual to date'), BI('البسط', 'Numerator')], [BI('مستهدف الخطة', 'Plan target'), BI('المقام: الفترة كاملة', 'Denominator: the whole period')]],
    steps: [BI('احسب المحصَّل والمستهدف لنفس الصف.', 'Compute actual and target for the same row.'), BI('اقسم دون تقريب مسبق ولا سقف.', 'Divide without early rounding or a cap.')],
    unit: PCT, level: BI('الخطة ثم الجهة ثم البلدية، من المجاميع', 'Plan, then entity, then municipality, from the sums'), period: BI('من بداية فترة الخطة حتى تاريخ الإغلاق', 'From the plan period start to the cut-off'), dateBasis: BI('تاريخ الإغلاق', 'The cut-off date'),
    sourceFields: BI('المحصَّل الفعلي حتى تاريخه + مستهدف الخطة', 'Actual to date + the plan target'),
    missing: BI('المستهدف ≤ 0 أو بلدية بلا تخصيص ← «غير متاح»؛ تتجاوز 100% عند التفوق مع بيان «تجاوز بمقدار X».', 'Target ≤ 0 or a municipality with no allocation → «not available»; above 100 % when exceeded, with «exceeded by X» stated.'),
    owner: OWN_PLAN, where: 'planBasis.js · achievementToDate; planMeasures.js · achievementToDate', notes: [SUMMED] },

  { key: 'remainingTarget', label: BI('المتبقي من مستهدف الخطة', 'Remaining plan target'), sources: ['tahseel'],
    brief: BI('max(المستهدف − المحصَّل حتى تاريخه، 0)؛ صفر عند تحقق المستهدف.', 'max(target − actual to date, 0); zero once the target is reached.'),
    definition: BI('الجزء من مستهدف الخطة الذي لم يُحصَّل بعد. عند تجاوز المستهدف يُعرض «تحقق المستهدف — تجاوز بمقدار X» ولا يوجد متبقٍ ولا وتيرة مطلوبة.', 'The part of the plan target still to be collected. Once the target is exceeded, «target reached — exceeded by X» is shown, with no remainder and no required pace.'),
    formula: BI('المتبقي = max(المستهدف − المحصَّل، 0)', 'Remaining = max(target − actual, 0)'),
    f: 'remaining = max(T - C(asOf), 0);  exceededBy = max(C - T, 0)',
    inputs: [[BI('مستهدف الخطة', 'Plan target'), BI('انظر تعريفه', 'See its definition')], [BI('المحصَّل الفعلي حتى تاريخه', 'Actual to date'), BI('انظر تعريفه', 'See its definition')]],
    steps: [BI('اطرح المحصَّل من المستهدف.', 'Subtract actual from the target.'), BI('إن كان الناتج سالبًا فالمتبقي صفر ويُسجَّل التجاوز.', 'If negative the remainder is zero and the excess is recorded.')],
    unit: SAR, level: BI('الجهة ثم الإجمالي؛ قابل للجمع', 'Entity, then total; additive'), period: FY, dateBasis: ASOF,
    sourceFields: BI('المحصَّل الفعلي حتى تاريخه + مستهدف الخطة', 'Actual to date + the plan target'),
    missing: BI('المستهدف ≤ 0 ← «لا مستهدف» (لا متبقٍ).', 'Target ≤ 0 → «no target» (no remainder).'),
    owner: OWN_PLAN, where: 'planBasis.js · remainingTarget / exceededBy', notes: [] },

  { key: 'requiredPace', label: BI('الوتيرة المطلوبة للمتبقي', 'Required pace'), sources: ['tahseel'],
    brief: BI('المتبقي من المستهدف ÷ الأيام (أو الأشهر بالأيام) المتبقية حتى 31 ديسمبر.', 'Remaining target ÷ the days (or day-based months) left until 31 December.'),
    definition: BI('ما يلزم تحصيله يوميًا وشهريًا لبلوغ المستهدف في نهاية السنة. الأشهر المتبقية تُحسب بالأيام وليست أشهرًا صحيحة (6 نوفمبر: 24÷30 + 1 = 1.8 شهر، 55 يومًا). يُقارن بالوتيرة الأخيرة وبأفضل شهر.', 'What must be collected per day and per month to reach the target at year end. The months left are counted in days, not whole months (6 November: 24÷30 + 1 = 1.8 months, 55 days). It is compared with the recent pace and the best month.'),
    formula: BI('اليومية = المتبقي ÷ الأيام المتبقية؛ الشهرية = المتبقي ÷ الأشهر المتبقية بالأيام', 'Daily = remaining ÷ remaining days; monthly = remaining ÷ day-based months left'),
    f: 'daily = remaining / remainingDays;  monthly = remaining / monthsLeft;  monthsLeft = (dim - d)/dim + (12 - m)',
    inputs: [[BI('المتبقي من المستهدف', 'Remaining target'), BI('البسط', 'Numerator')], [BI('الأيام المتبقية', 'Remaining days'), BI('من اليوم التالي لتاريخ التقرير حتى 31 ديسمبر', 'From the day after the reporting date to 31 December')]],
    steps: [BI('احسب المتبقي.', 'Compute the remainder.'), BI('احسب الأيام والأشهر المتبقية بالأيام.', 'Compute the remaining days and day-based months.'), BI('اقسم.', 'Divide.')],
    unit: BI('ريال سعودي لليوم / للشهر', 'SAR per day / per month'), level: BI('الإجمالي أو الجهة', 'Total or entity'), period: BI('من تاريخ التقرير حتى 31 ديسمبر', 'From the reporting date to 31 December'), dateBasis: ASOF,
    sourceFields: BI('المتبقي من المستهدف + تاريخ التقرير', 'Remaining target + the reporting date'),
    missing: BI('الأيام المتبقية = 0 أو المتبقي = 0 ← «لا مطلوب» (لا رقم بعد نهاية السنة).', 'Remaining days = 0 or remainder = 0 → «none required» (never a number after year end).'),
    owner: OWN_PLAN, where: 'planBasis.js · pace.required; remainingOf()', notes: [BI('تناسب الأيام اتفاقية موثّقة يمكن للمالية استبدالها (أيام العمل، موسمية).', 'Day proration is a documented convention Finance may replace (business days, seasonality).')] },

  { key: 'recentPace', label: BI('الوتيرة الأخيرة وأفضل شهر', 'Recent pace and best month'), sources: ['tahseel'],
    brief: BI('متوسط التحصيل الشهري لآخر 3 أشهر مكتملة، وأعلى شهر مكتمل في السنة.', 'The mean monthly receipts of the last 3 complete months, and the highest complete month of the year.'),
    definition: BI('الوتيرة الفعلية الأخيرة: متوسط آخر ثلاثة أشهر مكتملة (الشهر الجزئي لا يدخل أبدًا). أفضل شهر = أعلى شهر مكتمل. تُكتب نافذة الأشهر بجانب الرقم. تُقارَن بالوتيرة المطلوبة (×) ولا تُستخدم وحدها للحكم.', 'The latest actual pace: the mean of the last three complete months (a partial month is never included). Best month = the highest complete month. The window of months is printed beside the figure. It is compared with the required pace (×) and is not a verdict by itself.'),
    formula: BI('الأخيرة = متوسط التحصيل لآخر 3 أشهر مكتملة؛ الأفضل = max(الأشهر المكتملة)', 'Recent = mean receipts of the last 3 complete months; best = max(complete months)'),
    f: 'recent = mean(C_month for the last 3 complete months);  best = max(C_month over complete months)',
    inputs: [[BI('التحصيل الشهري', 'Monthly receipts'), BI('بتاريخ الدفع، للأشهر المكتملة فقط', 'By payment date, complete months only')]],
    steps: [BI('استبعد الشهر الجاري إن لم يكتمل.', 'Drop the current month if it is not complete.'), BI('خذ آخر 3 أشهر مكتملة.', 'Take the last 3 complete months.'), BI('احسب المتوسط وأعلى شهر.', 'Compute the mean and the highest month.')],
    unit: BI('ريال سعودي / شهر', 'SAR per month'), level: BI('الإجمالي أو الجهة', 'Total or entity'), period: BI('آخر 3 أشهر مكتملة', 'The last 3 complete months'), dateBasis: BI('تاريخ الدفع، الأشهر التقويمية المكتملة', 'Payment date, complete calendar months'),
    sourceFields: BI('السلسلة الشهرية للمحصَّل الفعلي', 'The monthly series of actual collections'),
    missing: BI('أقل من 3 أشهر مكتملة ← «لا يكفي سجل» (في يناير تُستخدم أشهر العام السابق إن وُجدت)؛ وغير المتاح ليس صفرًا.', 'Fewer than 3 complete months → «not enough record» (in January the previous year’s months are used if present); unavailable is never zero.'),
    owner: OWN_PLAN, where: 'planForecast.js · forecastPlan() · monthlyRate (baselineRate())', notes: [] },

  { key: 'forecastBaseline', label: BI('التوقع بنهاية السنة (خط الأساس)', 'Year-end forecast (baseline)'), sources: ['tahseel'],
    brief: BI('المحصَّل حتى تاريخه + الوتيرة الأخيرة × الأشهر المتبقية بالأيام؛ المنهج runrate3_v2 وغير مُواءَم مع فرق التوقع.', 'Actual to date + the recent pace × the day-based months left; method runrate3_v2, not aligned with the forecasting teams.'),
    definition: BI('خط أساس واحد قابل للشرح لكل الشاشات والتقارير والمساعد: يستمر متوسط آخر 3 أشهر مكتملة بلا تغيير، ويُضاف المتبقي من الشهر الحالي بالأيام. لا موسمية ولا استرداد متأخرات ولا أثر لإجراءات، ولا يستخدم المستهدف، ولا يقدّم نطاقًا ولا احتمالية. يُذكر معرّف المنهج ونافذته في كل مكان، ويُكتب «غير مُواءَم مع منهجية فرق التوقع — قيد التنسيق».', 'One explainable baseline for every screen, report and the assistant: the mean of the last 3 complete months continues unchanged, and the rest of the current month is added by days. No seasonality, no recovery of arrears, no action effect; it does not use the target and gives neither a range nor a probability. The method id and window are shown everywhere, with «not aligned with the forecasting teams’ methodology — coordination pending».'),
    formula: BI('التوقع = المحصَّل حتى تاريخه + الوتيرة الأخيرة × (المتبقي من الشهر الحالي ÷ أيامه + الأشهر الكاملة المتبقية)', 'Forecast = actual to date + recent pace × (the rest of the current month ÷ its days + the whole months left)'),
    f: 'F = C(asOf) + recent * monthsLeft(asOf);   method id runrate3_v2, window = last 3 complete months',
    inputs: [[BI('المحصَّل حتى تاريخه', 'Actual to date'), BI('نقطة البداية', 'The starting point')], [BI('الوتيرة الأخيرة', 'Recent pace'), BI('متوسط آخر 3 أشهر مكتملة', 'Mean of the last 3 complete months')], [BI('الأشهر المتبقية بالأيام', 'Day-based months left'), BI('انظر الوتيرة المطلوبة', 'See the required pace')]],
    steps: [BI('احسب الوتيرة الأخيرة من الأشهر المكتملة فقط.', 'Compute the recent pace from complete months only.'), BI('أضف المتبقي من الشهر الحالي بالأيام ثم الأشهر الكاملة.', 'Add the rest of the current month by days, then the whole months.'), BI('اطبع المنهج والنافذة وعبارة عدم المواءمة.', 'Print the method, the window and the non-alignment statement.')],
    unit: SAR, level: BI('النطاق المختار: الوزارة أو الجهات المتاحة أو جهة واحدة (من أشهرها المكتملة)؛ ولا تُجمع توقعات الجهات', 'The selected scope: the Ministry, the available entities or one entity (from its own complete months); entity forecasts are not summed'), period: BI('من تاريخ التقرير حتى 31 ديسمبر', 'From the reporting date to 31 December'), dateBasis: BI('تاريخ الدفع، الأشهر المكتملة', 'Payment date, complete months'),
    sourceFields: BI('السلسلة الشهرية للمحصَّل الفعلي (أشهر مكتملة)', 'The monthly series of actual collections (complete months)'),
    missing: BI('لا أشهر مكتملة كافية ← «لا يكفي سجل» ولا توقع؛ في 31 ديسمبر لا توقع (النتيجة بيان «تحقق / لم يتحقق»).', 'Not enough complete months → «not enough record», no forecast; on 31 December there is no forecast (the result is the statement «achieved / not achieved»).'),
    owner: OWN_PLAN, where: 'planForecast.js · forecastPlan(); revenueOutlook.js · forecastCore()',
    notes: [BI('السجل (22 شهرًا توضيحيًا) لا يتيح اختبار التوقع على ما كان معروفًا في كل تاريخ؛ الاختبار الرجعي المعروض عينة صغيرة وليس ضمانًا.', 'The record (22 illustrative months) cannot test the forecast on what was known at each date; the backtest shown is a small sample and not a guarantee.')] },

  { key: 'forecastAchievement', label: BI('نسبة تحقيق المستهدف المتوقعة بنهاية الفترة', 'Expected target achievement by the end of the period'), sources: ['tahseel'],
    brief: BI('التحصيل المتوقع بنهاية الفترة ÷ مستهدف الفترة كاملة؛ ليست احتمالية.', 'The expected collection by the end of the period ÷ the full-period target; not a probability.'),
    definition: BI('كم سيبلغ التحصيل من المستهدف إن استمرت الوتيرة الأخيرة. تُعرض مع مبلغ المتوقع والفجوة المتوقعة (فجوة متوقعة عن المستهدف أو فائض متوقع فوقه) معًا، بدل أي نسبة احتمال. لا سقف 100% ولا لون «ثقة».', 'How much of the target is reached if the recent pace continues. It is shown with the expected amount and the expected gap (an expected shortfall against the target or an expected surplus above it) together, in place of any probability. No 100 % cap and no «confidence» colour.'),
    formula: BI('المتوقعة = (المحصَّل حتى تاريخه + الوتيرة الأخيرة × الأشهر المتبقية بالأيام) ÷ مستهدف الفترة كاملة × 100', 'Expected = (actual to date + recent pace × the day-based months left) ÷ the full-period target × 100'),
    f: 'expectedAchievement = F / T * 100,  F = C(cutoff) + rate * Σ_months (daysAfterCutoff / monthDays);  gap = T - F  (shortfall > 0, surplus < 0)',
    inputs: [[BI('التحصيل المتوقع بنهاية الفترة', 'Expected collection by the end of the period'), BI('البسط', 'Numerator')], [BI('مستهدف الخطة', 'Plan target'), BI('المقام: الفترة كاملة', 'Denominator: the whole period')]],
    steps: [BI('احسب المتوقع والمستهدف لنفس الصف.', 'Compute the forecast and the target for the same row.'), BI('اقسم دون سقف واكتب الفجوة بإشارة صريحة.', 'Divide without a cap and write the gap with an explicit label.')],
    unit: PCT, level: BI('الخطة المختارة أو الأمانة أو البلدية (تُحسب من أشهرها؛ لا تُجمع توقعات الصفوف)', 'The selected plan, Amanah or municipality (from its own months; row forecasts are not summed)'), period: BI('من تاريخ الإغلاق حتى نهاية فترة الخطة', 'From the cut-off to the end of the plan period'), dateBasis: ASOF,
    sourceFields: BI('التوقع بنهاية الفترة + مستهدف الخطة', 'The forecast for the end of the period + the plan target'),
    missing: BI('لا توقع، أو المستهدف ≤ 0، أو بلدية بلا تخصيص (يبقى مبلغ المتوقع ويُحجب النسبة)، أو فترة لم تبدأ، أو مسودة ← «غير متاح» مع السبب. فترة منتهية ← نتيجة نهائية لا توقع.', 'No forecast, target ≤ 0, a municipality with no allocation (the amount stays, the percentage is withheld), a period that has not started → «not available» with the reason. A period that has ended → a final result, not a forecast.'),
    owner: OWN_PLAN, where: 'planForecast.js · forecastPlan().expectedAchievementPct; planMeasures.js · expected', notes: [] },

  { key: 'forecastGap', label: BI('الفجوة المتبقية بنهاية السنة', 'Remaining year-end gap'), sources: ['tahseel'],
    brief: BI('المستهدف − التوقع؛ = المتأخر حتى تاريخه + الجزء غير المغطى من الخطة المتبقية.', 'Target − forecast; = behind at the cut-off + the part of the remaining plan the forecast does not cover.'),
    definition: BI('الفرق الموقَّع بين مستهدف الخطة والتوقع. جسر محاسبي دقيق: المستهدف − التوقع = (المخطط − المحصَّل حتى تاريخه) + ((المستهدف − المخطط) − (التوقع − المحصَّل)). الجزء الأول متأخر قائم، والثاني ما لا يغطيه المحصَّل المتوقع من الخطة المتبقية.', 'The signed difference between the plan target and the forecast. An exact bridge: target − forecast = (planned − actual to date) + ((target − planned) − (forecast − actual)). The first part is the shortfall already incurred, the second what the expected remaining receipts do not cover of the remaining plan.'),
    formula: BI('الفجوة = المستهدف − التوقع', 'Gap = target − forecast'),
    f: 'gap = T - F = (P - C) + ((T - P) - (F - C))',
    inputs: [[BI('مستهدف الخطة', 'Plan target'), BI('انظر تعريفه', 'See its definition')], [BI('التوقع بنهاية السنة', 'Year-end forecast'), BI('انظر تعريفه', 'See its definition')]],
    steps: [BI('اطرح التوقع من المستهدف.', 'Subtract the forecast from the target.'), BI('فصّل الفجوة إلى «متأخر حتى تاريخه» و«غير مغطى».', 'Split it into «behind to date» and «uncovered».')],
    unit: SAR, level: BI('النطاق المختار (الوزارة أو الجهات المتاحة أو جهة واحدة)', 'The selected scope (the Ministry, the available entities or one entity)'), period: BI('العام المالي', 'Fiscal year'), dateBasis: ASOF,
    sourceFields: BI('المستهدف + المخطط حتى تاريخه + المحصَّل + التوقع', 'Target + planned to date + actual + forecast'),
    missing: BI('لا توقع ← لا فجوة؛ فجوة سالبة = تفوق متوقع وتُعرض كذلك.', 'No forecast → no gap; a negative gap = expected excess and is shown as such.'),
    owner: OWN_PLAN, where: 'planForecast.js · forecastPlan().gap / bridge', notes: [] },

  { key: 'gapContribution', label: BI('المساهمة في فجوة المستهدف', 'Contribution to the target gap'), sources: ['tahseel'],
    brief: BI('انحراف كل جهة (المخطط − المحصَّل) وحصتها من مجموع الانحراف؛ على مستوى الجهة فقط.', 'Each entity’s shortfall (planned − actual) and its share of the total; at entity level only.'),
    definition: BI('كم تسهم كل جهة في الانحراف الكلي حتى تاريخه. مجموع مساهمات الجهات = المخطط − المحصَّل بدقة؛ الجهات المتقدمة عن الخطة مساهمتها سالبة وتُعرض منفصلة. لا تُعرَّف مساهمة على مستوى مصدر الإيراد لأنه لا مستهدف لكل مصدر؛ يُعرض هناك حصة التحصيل ونسبته فقط.', 'How much each entity contributes to the total deviation to date. The entities’ contributions add up exactly to planned − actual; entities ahead of plan carry a negative contribution and are shown apart. No contribution is defined by revenue source because no per-source target exists; collected share and rate are shown there instead.'),
    formula: BI('المساهمة_i = المخطط_i − المحصَّل_i؛ الحصة = المساهمة_i ÷ Σ المساهمات', 'Contribution_i = planned_i − actual_i; share = contribution_i ÷ Σ contributions'),
    f: 'g_i = P_i - C_i;  share_i = g_i / sum_j g_j;  sum_i g_i = P - C',
    inputs: [[BI('المخطط حتى تاريخه للجهة', 'Entity planned to date'), BI('من مستهدف الجهة', 'From the entity target')], [BI('المحصَّل الفعلي للجهة', 'Entity actual'), BI('حتى تاريخ التقرير', 'To the reporting date')]],
    steps: [BI('احسب مستهدف ومخطط كل جهة على المجموعة الكاملة.', 'Compute every entity’s target and planned figure on the full set.'), BI('اطرح المحصَّل.', 'Subtract actual.'), BI('رتّب تنازليًا واحسب الحصة من مجموع ما أُدخل.', 'Rank descending and compute the share of what is supplied.')],
    unit: SAR, level: BI('الجهة فقط (لا مصدر)', 'Entity only (no source)'), period: FY, dateBasis: ASOF,
    sourceFields: BI('مستهدف الجهة + ملف التوزيع + المحصَّل الفعلي للجهة', 'Entity target + plan profile + entity actual'),
    missing: BI('جهة بلا مستهدف (الديوان) لا مساهمة لها؛ المجموع غير الموجب ← لا حصة.', 'An entity without a target (headquarters) has no contribution; a non-positive total → no share.'),
    owner: OWN_PLAN, where: 'planBasis.js · entities[]; server/planningActions.js · contributionToGap',
    notes: [BI('المقيَّد يرى مساهمات جهاته فقط، محسوبة على المجموعة الكاملة؛ وتُكتب الحصة نسبةً إلى ما أُدخل.', 'A restricted viewer sees the contributions of their own entities, computed on the full set; the share is relative to what is supplied.')] },

  { key: 'actionClasses', label: BI('فئات الإجراء (A / B / C / D / U / E)', 'Action classes (A / B / C / D / U / E)'), sources: ['tahseel', 'efaa'],
    brief: BI('تقسيم الرصيد القائم إلى فئات إجراء: كل فاتورة في فئة واحدة وسطر واحد؛ لا تقدير للاسترداد.', 'The standing balance split into action classes: one invoice, one class, one line; no recovery estimate.'),
    definition: BI('A محجوز: إجراء قائم أو اعتراض أو ربط غير محسوم أو إحالة غير مؤهلة — لا إحالة جديدة. B متأخر حتى 180 يومًا — قابل للمتابعة. C مستحق خلال السنة (لم يحن بعد). D متأخر أكثر من 180 يومًا — قرار منفصل وليس دفعة تحصيل. U تاريخ الاستحقاق غير متاح. E يستحق بعد نهاية السنة. الأسبقية A > U > D > B > C > E. مجموع الأسطر = الرصيد القائم بالريال. الأثر المتوقع «غير متاح». الحد 180 يومًا وانتماء الإجراءات القائمة إلى A توصية قرار D-10 تنتظر تأكيد مسؤولي التحصيل.', 'A blocked: an existing action, an objection, unresolved linkage or an ineligible referral — no new referral. B overdue up to 180 days — actionable. C due by year end (not yet due). D overdue more than 180 days — a separate decision, not a collection push. U due date unavailable. E due after year end. Precedence A > U > D > B > C > E. The lines add up to the standing balance to the riyal. Expected impact is «not available». The 180-day line and A’s membership are the D-10 recommendation, pending the collection owners.'),
    formula: BI('فئة الفاتورة = أول شرط يتحقق بالترتيب A, U, D, B, C, E', 'Invoice class = the first condition that holds in the order A, U, D, B, C, E'),
    f: 'class(invoice) = first of: A blocked | U no due date | D overdue > 180 d | B overdue <= 180 d | C due <= 31 Dec | E due later;   sum(lines) = stock net unpaid',
    inputs: [[BI('المتبقي على الفاتورة', 'Remaining on the invoice'), BI('غير المسدد، بعد الاستبعاد والإلغاء', 'Unpaid, after exclusions and cancellations')], [BI('تاريخ الاستحقاق', 'Due date'), BI('يُقارَن بتاريخ التقرير وبنهاية السنة', 'Compared with the reporting date and year end')], [BI('حالة الإجراء', 'Action state'), BI('إنفاذ / اعتراض / ربط', 'Enforcement / objection / linkage')]],
    steps: [BI('خذ الفواتير المفتوحة غير المستبعدة ولا الملغاة.', 'Take the open invoices that are neither excluded nor cancelled.'), BI('صنّف كل فاتورة مرة واحدة بالأسبقية.', 'Classify each invoice once, by precedence.'), BI('جمّع الأسطر حسب الجهة × المصدر × الفئة.', 'Group the lines by entity × source × class.')],
    unit: SAR, level: BI('الفاتورة ← سطر (جهة × مصدر × فئة)؛ قابل للجمع', 'Invoice → a line (entity × source × class); additive'), period: BI('رصيد قائم في تاريخ التقرير (كل سنوات الإصدار)', 'Standing balance at the reporting date (all issue years)'), dateBasis: BI('تاريخ الاستحقاق وتاريخ التقرير؛ نهاية السنة للفئتين C وE', 'Due date and reporting date; year end for classes C and E'),
    sourceFields: BI('المتبقي، تاريخ الاستحقاق، حالة الاستبعاد والإلغاء، روابط أوامر التنفيذ، حالة الاعتراض', 'Remaining, due date, exclusion and cancellation status, enforcement-order links, objection status'),
    missing: BI('لا تاريخ استحقاق ← الفئة U (لا تُعدّ متأخرة)؛ لا أثر متوقع ولا استرداد مقدَّر.', 'No due date → class U (never overdue); no expected impact and no estimated recovery.'),
    owner: OWN_COLL, where: 'server/planningActions.js · planClassOf() / actionLines()',
    notes: [BI('المستبعد والملغى خارج الأسطر ويُعرضان منفصلين.', 'Excluded and cancelled invoices are outside the lines and reported apart.')] },

  { key: 'planVsPlan', label: BI('نسبة الإنجاز مقابل المخطط', 'Achievement against plan'), sources: ['tahseel'],
    brief: BI('المحصَّل حتى تاريخه ÷ المخطط حتى تاريخه.', 'Actual to date ÷ planned to date.'),
    definition: BI('كم بلغ التحصيل مما كان مخططًا بلوغه حتى تاريخ الإغلاق. يُقرأ مع الانحراف النقدي الموقّع. لا تصنيف لفظيًا للحالة.', 'How much of what was planned to be collected by the cut-off has been collected. Read together with the signed monetary deviation. There is no verbal status label.'),
    formula: BI('نسبة الإنجاز مقابل المخطط = المحصَّل حتى تاريخه ÷ المخطط حتى تاريخه × 100', 'Achievement against plan = actual to date ÷ planned to date × 100'),
    f: 'vsPlan = C(cutoff) / P(cutoff) * 100  when P > 0',
    inputs: [[BI('المحصَّل حتى تاريخه', 'Actual to date'), BI('البسط', 'Numerator')], [BI('المخطط حتى تاريخه', 'Planned to date'), BI('المقام', 'Denominator')]],
    steps: [BI('احسب المحصَّل والمخطط لنفس الصف وتاريخ الإغلاق.', 'Compute actual and planned for the same row and cut-off.'), BI('اقسم؛ المخطط صفر ← غير متاح.', 'Divide; planned zero → not available.')],
    unit: PCT, level: BI('الخطة ثم الجهة ثم البلدية', 'Plan, then entity, then municipality'), period: BI('من بداية فترة الخطة حتى تاريخ الإغلاق', 'From the plan period start to the cut-off'), dateBasis: BI('تاريخ الإغلاق', 'The cut-off date'),
    sourceFields: BI('المحصَّل حتى تاريخه + المخطط حتى تاريخه', 'Actual to date + planned to date'),
    missing: BI('المخطط صفر أو لا مستهدف أو بلدية بلا تخصيص ← «غير متاح» مع السبب.', 'Planned zero, no target or a municipality with no allocation → «not available» with the reason.'),
    owner: OWN_PLAN, where: 'planBasis.js · vsPlanRatio; planMeasures.js · vsPlanRatio', notes: [] },

  { key: 'planConcepts', label: BI('الخطة والمستهدف والتخصيص والتوزيع', 'Plan, target, allocation and distribution'), sources: ['tahseel'],
    brief: BI('خطة مسمّاة محفوظة: نطاق وفترة ومستهدف وتخصيص من الأعلى إلى الأسفل وتوزيع شهري صريح.', 'A saved named plan: scope, period, target, top-down allocation and an explicit monthly distribution.'),
    definition: BI('الخطة سجل محفوظ في خدمة البيانات له معرّف ثابت واسم فريد ومالك هو منشئه (لا يتغير) وآخر محرّر. النطاق: الوزارة أو جهات محددة؛ التخصيص: مبالغ صحيحة للجهات يجب أن تساوي المستهدف عند الحفظ، ويمكن تخصيص جزء من مبلغ الأمانة لبلدياتها (والباقي «غير موزع على البلديات»). التوزيع الشهري: متساوٍ (افتراض صريح) أو يدوي. «حفظ الخطة» يحدّث الخطة نفسها إن كان للمستخدم حق تعديلها، وإلا يُحفظ كخطة جديدة باسمه؛ والخطة الافتراضية للنظام توضيحية ولا يكتب فوقها أحد. الخطة الافتراضية لكل مستخدم تخصه وحده، أما الخطة المرجعية للتقارير فتُعيَّن صراحةً لكل عام ولا تتأثر بها. عرض الأمانة/البلدية مرشّح عرض ولا يغيّر الخطة.', 'A plan is a record stored in the data service with a stable id, a unique name, an owner who is its creator (never changed) and a last editor. Scope: the Ministry or selected entities; allocation: whole riyals per entity that must equal the target when saving, and part of an Amanah amount may be allocated to its municipalities (the rest is «not distributed to municipalities»). Monthly distribution: equal (an explicit assumption) or manual. «Save plan» updates the plan itself when the user may edit it, otherwise it is saved as a new plan of theirs; the system default plan is illustrative and nobody overwrites it. A user\'s default plan is theirs alone, while the reference plan for reports is set explicitly per year and is unaffected by it. The Amanah / municipality view is a display filter and never changes the plan.'),
    formula: BI('الحفظ يتطلب: المستهدف > 0 · مجموع التخصيص = المستهدف · التخصيص ضمن النطاق · توزيع شهري محدد · الأشهر اليدوية = 100% · مجموع البلديات ≤ مبلغ الأمانة', 'Saving requires: target > 0 · Σ allocation = target · allocation inside the scope · a chosen monthly distribution · manual months = 100 % · Σ municipalities ≤ the Amanah amount'),
    f: 'save ⇔ T > 0 ∧ Σ alloc = T ∧ alloc ⊆ scope ∧ profile ∈ {equal, manual} ∧ Σ bp = 10000 ∧ Σ muni ≤ alloc(entity)',
    inputs: [[BI('محتوى الخطة', 'Plan content'), BI('الاسم والنطاق والفترة والمستهدف والتخصيص والتوزيع', 'Name, scope, period, target, allocation and distribution')]],
    steps: [BI('عدّل نسخة عمل في المتصفح؛ تُعرض كمعاينة حية ولا يُخزَّن شيء.', 'Edit a working copy in the browser; it is shown as a live preview and nothing is stored.'), BI('«حفظ الخطة» يتحقق من الاسم والإعداد ثم يحفظ.', '«Save plan» checks the name and the configuration, then saves.')],
    unit: BI('ريال صحيح؛ نقطة أساس للتوزيع اليدوي', 'Whole riyals; basis points for the manual distribution'), level: BI('الخطة', 'Plan'), period: BI('فترة الخطة', 'The plan period'), dateBasis: BI('لا يتأثر بتاريخ التقرير', 'Independent of the reporting date'),
    sourceFields: BI('سجل الخطة في خدمة البيانات (التخزين المحلي للعرض التجريبي)', 'The plan record in the data service (local demo storage)'),
    missing: BI('خطة لا يراها المستخدم بكل جهاتها تظهر «إجمالي الجهات المتاحة لك» بلا تخصيص كامل ولا إجمالي أمانة لمن نطاقه بلديات فقط.', 'A plan the user cannot see in full shows «total of the entities available to you», with no complete allocation and no Amanah total for a municipal-only user.'),
    owner: OWN_PLAN, where: 'planRules.js · saveChecks() / allocationSummary() / municipalSummary(); server/plans/*',
    notes: [BI('التخزين الحالي محلي للعرض التجريبي وغير معتمد للنشر.', 'The current storage is local demo storage, not approved for deployment.')] },

  { key: 'planDates', label: BI('تواريخ الأرقام', 'The dates of the figures'), sources: ['tahseel'],
    brief: BI('تاريخ الإغلاق · آخر تاريخ بيانات فعلية · آخر شهر مكتمل في نافذة التوقع · وقت توليد التوقع.', 'Reporting cut-off · latest actual data date · last complete month of the forecast window · forecast generated at.'),
    definition: BI('أربعة تواريخ مختلفة لا تُخلط: (1) تاريخ الإغلاق = الأصغر بين اليوم ونهاية الفترة وآخر تاريخ بيانات؛ (2) آخر تاريخ بيانات فعلية؛ (3) آخر شهر مكتمل استُخدم في نافذة الأشهر الثلاثة، وقد ينتهي قبل تاريخ الإغلاق وقد يبدأ قبل الفترة؛ (4) وقت توليد التوقع. تُعرض في تفصيل قسم «الموقف حتى تاريخه».', 'Four different dates that are never mixed: (1) the cut-off = the earliest of today, the period end and the latest data date; (2) the latest actual data date; (3) the last complete month used in the 3-month window, which may end before the cut-off and start before the period; (4) the time the forecast was generated. They are shown in the detail of the «Position to date» section.'),
    formula: BI('تاريخ الإغلاق = min(اليوم، نهاية الفترة، آخر تاريخ بيانات)', 'Cut-off = min(today, period end, latest data date)'),
    f: 'cutoff = min(today, period.end, latestDataDate);  lastCompleteMonth = last calendar month fully on or before the cut-off',
    inputs: [[BI('اليوم وآخر بيانات وفترة الخطة', 'Today, the latest data and the plan period'), BI('مدخلات التاريخ', 'The date inputs')]],
    steps: [BI('احسب تاريخ الإغلاق.', 'Compute the cut-off.'), BI('اختر آخر ثلاثة أشهر مكتملة مرصودة قبله.', 'Take the last three complete observed months before it.')],
    unit: BI('تاريخ', 'Date'), level: BI('الخطة والعرض المختار', 'The plan and the selected view'), period: BI('تاريخ الإغلاق', 'The cut-off'), dateBasis: BI('تاريخ الدفع', 'Payment date'),
    sourceFields: BI('تاريخ الخدمة وآخر تاريخ بيانات', 'The service date and the latest data date'),
    missing: BI('لا بيانات بعد بداية الفترة ← «لا بيانات فعلية»؛ لا أشهر مكتملة كافية ← لا توقع.', 'No data since the period start → «no actual data»; not enough complete months → no forecast.'),
    owner: OWN_PLAN, where: 'planBasis.js · reportingCutoff / lastCompleteMonthBefore(); planForecast.js · forecastGeneratedAt', notes: [] },

  { key: 'forecastAlignment', label: BI('قواعد مواءمة التوقع', 'Forecast alignment rules'), sources: ['tahseel'],
    brief: BI('التوقع = المحصَّل حتى الإغلاق + متوسط آخر 3 أشهر مكتملة مرصودة × الأيام المتبقية من الفترة؛ يُرفض أي مدخل لا يطابق الخطة.', 'Forecast = collected to the cut-off + the mean of the last 3 complete observed months × the days left in the period; any input that does not match the plan is rejected.'),
    definition: BI('المحصَّل حتى الإغلاق (بما فيه الشهر الجزئي) يُحتسب مرة واحدة. الوتيرة = متوسط آخر ثلاثة أشهر مكتملة مرصودة؛ الشهر غير المرصود يُستبعد ولا يُعدّ صفرًا؛ وأقل من ثلاثة أشهر ← «لا يكفي سجل» دون نسبة. المتبقي = Σ لكل شهر (الأيام بعد الإغلاق ÷ أيام الشهر). يُرفض (دون رقم) أي مدخل بيانات لا يطابق الخطة أو الإصدار أو النطاق أو الفترة أو تاريخ الإغلاق. الفترة المنتهية: نتيجة نهائية بلا توقع؛ الفترة التي لم تبدأ والمستهدف الصفري والمسودة: لا توقع. احتمالية بلوغ المستهدف غير مقدَّرة (انظر مدخلها).', 'The collected amount to the cut-off (including the partial month) is counted once. The rate = the mean of the last three complete observed months; an unobserved month is excluded and never counted as zero; fewer than three → «not enough history» with no percentage. The remainder = Σ per month (days after the cut-off ÷ month days). Any data input that does not match the plan, version, scope, period or cut-off is rejected (no number). A period that has ended: a final result with no forecast; a period that has not started, a zero target or a draft: no forecast. The probability of reaching the target is not estimated (see its entry).'),
    formula: BI('التوقع = المحصَّل + الوتيرة × Σ (أيام ما بعد الإغلاق ÷ أيام الشهر)', 'Forecast = collected + rate × Σ (days after the cut-off ÷ month days)'),
    f: 'F = C + rate * Σ_m (daysAfterCutoff_m / monthDays_m);  rate = mean(last 3 complete observed months);  method id runrate3_v2',
    inputs: [[BI('السلسلة الشهرية', 'The monthly series'), BI('الأشهر الثلاثة الأخيرة المكتملة المرصودة', 'The last three complete observed months')], [BI('أيام الفترة المتبقية', 'Days left in the period'), BI('لكل شهر بنسبة أيامه', 'Per month by its day fraction')]],
    steps: [BI('تحقق من هوية المدخل مقابل الخطة.', 'Check the identity of the input against the plan.'), BI('احسب الوتيرة ثم المتبقي بالأيام.', 'Compute the rate, then the remainder by days.')],
    unit: SAR, level: BI('الخطة أو الأمانة أو البلدية المختارة', 'The selected plan, Amanah or municipality'), period: BI('من تاريخ الإغلاق حتى نهاية الفترة', 'From the cut-off to the end of the period'), dateBasis: BI('تاريخ الدفع، الأشهر المكتملة', 'Payment date, complete months'),
    sourceFields: BI('السلسلة الشهرية للمحصَّل (أشهر مكتملة مرصودة)', 'The monthly series of collections (complete observed months)'),
    missing: BI('أشهر غير كافية ← «لا يكفي سجل»؛ مدخل غير مطابق ← لا رقم.', 'Not enough months → «not enough history»; a mismatched input → no number.'),
    owner: OWN_PLAN, where: 'planForecast.js · forecastPlan()',
    notes: [BI('خط أساس غير مُواءَم مع منهجية فرق التوقع — قيد التنسيق، ولا نطاق ثقة له.', 'A baseline not aligned with the forecasting teams’ methodology — coordination pending — and with no confidence range.')] },

  { key: 'equalDistribution', label: BI('التوزيع المتساوي (افتراض)', 'Equal distribution (assumption)'), sources: ['tahseel'],
    brief: BI('تقسيم المستهدف بالتساوي على أيام الأشهر؛ افتراض صريح يُكتب بجانب الرقم.', 'Splitting the target equally over the months by days; an explicit assumption printed beside the figure.'),
    definition: BI('عند اختيار «توزيع متساوٍ» يأخذ كل شهر كامل وزنًا 1 ويأخذ الشهر الجزئي في أول الفترة أو آخرها كسر أيامه، والمجموع دقيق بالريال بأكبر باقٍ. هو افتراض لا موسمية مستنتجة ولا خطة شهرية مؤكدة، ويُكتب «توزيع متساوٍ — افتراض» بجانب المخطط حتى تاريخه. التوزيع اليدوي بنقاط الأساس بديل صريح ولا يُعاد تطبيعه بصمت.', 'With «equal distribution» every whole month weighs 1 and a partial first or last month weighs its day fraction; the sum is exact to the riyal by largest remainder. It is an assumption, not an inferred seasonality nor a confirmed monthly plan, and «equal distribution — an assumption» is printed beside the planned-to-date figure. The manual distribution in basis points is the explicit alternative and is never rescaled silently.'),
    formula: BI('مبلغ الشهر = المستهدف × (وزن الشهر ÷ Σ الأوزان)', 'Month amount = target × (month weight ÷ Σ weights)'),
    f: 'amount[m] = apportion(T, weights);  weight[m] = days(m in period) / monthDays(m)',
    inputs: [[BI('المستهدف والفترة', 'Target and period'), BI('انظر مستهدف الخطة', 'See the plan target')]],
    steps: [BI('احسب وزن كل شهر.', 'Compute each month weight.'), BI('وزّع بأكبر باقٍ واعرض باقي التقريب.', 'Apportion by largest remainder and show the rounding remainder.')],
    unit: SAR, level: BI('الخطة ثم الجهة', 'Plan, then entity'), period: BI('فترة الخطة', 'The plan period'), dateBasis: BI('الشهر التقويمي', 'Calendar month'),
    sourceFields: BI('محتوى الخطة المحفوظة: نمط التوزيع', 'The saved plan content: the distribution profile'),
    missing: BI('لا نمط محدد ← لا يُحفظ؛ لا يُختار «متساوٍ» بصمت.', 'No profile chosen → it cannot be saved; «equal» is never chosen silently.'),
    owner: OWN_FIN, where: 'planMath.js · distributionWeights() / monthAmounts()', notes: [] },

  { key: 'probabilityStatus', label: BI('احتمالية تحقيق المستهدف: غير مقدَّرة', 'Probability of reaching the target: not estimated'), sources: ['tahseel'],
    brief: BI('لا تتوفر بيانات كافية لتقدير احتمالية موثوقة؛ لا تُعرض نسبة احتمال.', 'There is not enough data for a reliable probability; no probability figure is shown.'),
    definition: BI('الاحتمالية هي P(المحصَّل + الإيرادات المستقبلية ≥ المستهدف) بشرط منهج ونافذة وافتراضات مُعلنة، وتُعرض فقط حين تكون الحالة «مدعومة». السجل الحالي لا يدعمها: أقل من 36 شهرًا مكتملًا، ولا سجل لمستهدفات سابقة معتمدة، ولا تاريخ تحميل للمدفوعات يتيح اختبار التوقع على ما كان معروفًا في كل تاريخ. لذلك لا يُعرض رقم، ولا تُستعمل نسبة التوقع إلى المستهدف بديلًا عنها، ويُعرض «التوقع بنهاية السنة» والفجوة والافتراضات. المطلوب لتقديرها: ≥ 36 شهرًا من مدفوعات «تحصيل» بتاريخَي الدفع والتحميل، ومستهدفات وخطط معتمدة بإصدارات لثلاث سنوات على الأقل، وتواريخ استحقاق وتاريخ حالات الفواتير، ودفعات استثنائية مؤكدة من المالية، وسجل تغيّر النطاق والعمليات، وسجل ربط الجهة بالمصدر.', 'The probability is P(actual + future receipts ≥ target) conditional on a stated method, window and assumptions, and is shown only when its status is «supported». The current record does not support it: fewer than 36 complete months, no record of earlier approved targets, and no load date on payments to test the forecast on what was known at each date. So no figure is shown, the forecast ÷ target ratio is never used instead, and the «year-end forecast», the gap and the assumptions are shown. Needed to estimate it: ≥ 36 months of Tahseel payments with payment and load dates, approved targets and plans by version for at least three years, due dates and invoice status history, one-offs confirmed by Finance, a scope / process change log, and the entity-to-source mapping history.'),
    formula: BI('غير مقدَّرة — لا معادلة معروضة', 'Not estimated — no formula is displayed'),
    f: 'probabilityStatus = unsupported  (message: "not enough data to estimate a reliable probability")',
    inputs: [[BI('عدد الأشهر المكتملة', 'Complete months'), BI('أقل من 36', 'Fewer than 36')], [BI('مستهدفات سابقة معتمدة', 'Earlier approved targets'), BI('غير متوفرة', 'Not available')], [BI('تاريخ تحميل المدفوعات', 'Payment load date'), BI('غير متوفر', 'Not available')]],
    steps: [BI('تحقق من كفاية السجل وإمكانية الاختبار الرجعي.', 'Check that the record is long enough and a backtest is possible.'), BI('إن لم يكفِ: اعرض الرسالة والسبب ولا رقم.', 'If not: show the message and the reason, no number.')],
    unit: BI('لا وحدة (غير مقدَّرة)', 'No unit (not estimated)'), level: BI('النطاق المختار (الوزارة أو الجهات المتاحة أو جهة واحدة)', 'The selected scope (the Ministry, the available entities or one entity)'), period: BI('العام المالي', 'Fiscal year'), dateBasis: ASOF,
    sourceFields: BI('مطلوبة وغير متوفرة: تاريخ تحميل المدفوعات، المستهدفات المعتمدة بإصداراتها، سجل ≥ 36 شهرًا', 'Required and not available: payment load date, approved targets by version, a ≥ 36-month record'),
    missing: BI('الحالة دائمًا «غير مدعومة» حتى تتوفر البيانات؛ لا صفر ولا 1% ولا نسبة حدّية.', 'The status is «unsupported» until the data exist; never 0, never 1 %, never a floor value.'),
    owner: BI('مالكو البيانات (قرار D-09) — مقترح، يُؤكَّد', 'Data owners (decision D-09) — suggested, to be confirmed'), where: 'planForecast.js · PROBABILITY_MESSAGE / PROBABILITY_REASON',
    notes: [BI('أُزيلت نسبة «الاحتمال» القديمة وسبب «الفوترة غير كافية» و«الحد الأقصى الممكن»: لا أساس إحصائي لها.', 'The old «probability», the «billing is insufficient» reason and the «maximum possible» are removed: they had no statistical basis.')] }
];

// ---- PD1: the content of the former «طريقة الحساب» panel of /planning moved here. Every metric now also carries the filters it honours and its assumptions / limitations (the symbolic formula `f` and the code
// location `where` were already here; the dictionary pages print all of them). `moreNotes` are appended to the metric's `notes`.
const F_SRC_NA = BI('مصدر الإيراد لا يغيّره: لا مستهدف لمصدر الإيراد، واختيار المصدر في الصفحة يضيّق جدول «أين نركز» فقط.', 'The revenue source does not change it: there is no per-source target, and choosing a source on the page narrows only the «where to focus» table.');
const F_ACCESS = BI('نطاق وصول المستخدم (المؤسسة / الجغرافيا) يحدد الجهات المتاحة له، ويُكتب «إجمالي الجهات المتاحة لك» حين يضيق العرض.', 'The viewer’s access scope (organisation / geography) decides which entities are available; the total is labelled «Total of the entities available to you» when the view is narrowed.');
const filt = (ar, en) => BI(`${ar} ${F_SRC_NA.ar} ${F_ACCESS.ar}`, `${en} ${F_SRC_NA.en} ${F_ACCESS.en}`);
const EXTRA = {
  annualTarget: { filters: filt('الخطة المختارة + عرض الأمانة / البلدية (جهة واحدة تعرض مخصصها؛ بلدية بلا تخصيص: لم يُحدد مستهدف).', 'The selected plan + the Amanah / municipality view (one entity shows its allocation; a municipality with none: no target set).'),
    assumptions: [BI('المستهدف مُدخل في الخطة وليس معادلة ميزانية؛ والخطة الافتراضية للنظام توضيحية.', 'The target is typed in the plan, not a budget formula; the system default plan is illustrative.')] },
  actualToDate: { filters: filt('العام المالي + الأمانة / الجهة؛ التحصيل يُجلب من خدمة البيانات ضمن نطاق وصول المستخدم.', 'Fiscal year + Amanah / entity; receipts come from the data service inside the viewer’s access scope.'),
    assumptions: [BI('أساس تاريخ الدفع على أي فاتورة، غير «المحصّل على فواتير الفترة»؛ يُعرض الجسر بينهما.', 'Payment-date basis on any invoice, not «collected on the period’s invoices»; the bridge between the two is shown.'), BI('لا تاريخ تحميل للمدفوعات في العرض: تاريخ آخر بيانات = اليوم، وتظهر «بيانات غير محدّثة» إن تأخر عن اليوم أكثر من 3 أيام.', 'The demo has no payment load date: the latest data date is today, and «data not up to date» appears when it lags today by more than 3 days.')] },
  plannedToDate: { filters: filt('الخطة المختارة + عرض الأمانة / البلدية؛ لا يعتمد على المحصَّل الفعلي.', 'The selected plan + the Amanah / municipality view; independent of the actual collections.'),
    assumptions: [BI('التوزيع المتساوي افتراض يُكتب بجانب الرقم في كل شاشة وتقرير، والتوزيع اليدوي بديل صريح.', 'The equal distribution is an assumption printed beside the figure on every screen and report; the manual distribution is the explicit alternative.')] },
  planDeviation: { filters: filt('الخطة المختارة + عرض الأمانة / البلدية؛ أشرطة المقارنة تعرض صفوف الخطة مع «أخرى» حتى يتطابق مجموعها مع الانحراف.', 'The selected plan + the Amanah / municipality view; the comparison bars show the plan rows with «other» so that they add up to the deviation.'),
    assumptions: [BI('لا تصنيف لفظي: الإشارة والمبلغ هما القراءة.', 'No verbal label: the sign and the amount are the reading.')],
    moreNotes: [BI('صف «غير موزع على البلديات» يضم ما لم يُخصَّص لبلدية والتحصيل غير المنسوب لبلدية مرجعية، فيتطابق مجموع صفوف الأمانة مع الأمانة.', 'The «not distributed to municipalities» row holds what is not allocated to a municipality and the collections not attributed to a reference municipality, so the Amanah rows add up to the Amanah.')] },
  planAchievement: { filters: filt('الخطة المختارة + عرض الأمانة / البلدية.', 'The selected plan + the Amanah / municipality view.'),
    assumptions: [BI('المقام مستهدف الخطة المحفوظة؛ والنسبة غير مقيّدة بـ 100%.', 'The denominator is the saved plan\'s target; the ratio is not capped at 100 %.')],
    moreNotes: [BI('أربع نسب مختلفة لا يُستعاض ببعضها: نسبة تحقيق المستهدف حتى تاريخه = المحصّل ÷ مستهدف الفترة كاملة · نسبة الإنجاز مقابل المخطط = المحصّل ÷ المخطط حتى تاريخه · نسبة تحقيق المستهدف المتوقعة بنهاية الفترة = المتوقع ÷ مستهدف الفترة كاملة · نسبة التحصيل = المحصّل ÷ صافي المفوتر.', 'Four different percentages never used for one another: target achievement to date = collected ÷ the full-period target · achievement against plan = collected ÷ planned to date · expected target achievement by the end of the period = expected ÷ the full-period target · collection rate = collected ÷ net billed.')] },
  remainingTarget: { filters: filt('العام المالي + الأمانة / الجهة.', 'Fiscal year + Amanah / entity.'), assumptions: [] },
  requiredPace: { filters: filt('العام المالي (السنة الجارية فقط) + الأمانة / الجهة.', 'Fiscal year (the current year only) + Amanah / entity.'),
    assumptions: [BI('تناسب الأيام اتفاقية موثّقة؛ لا أيام عمل ولا موسمية. لا وتيرة بعد نهاية السنة أو بعد تحقق المستهدف.', 'Day proration is a documented convention; no business days and no seasonality. There is no pace after the year end or once the target is reached.')] },
  recentPace: { filters: filt('العام المالي + الأمانة / الجهة.', 'Fiscal year + Amanah / entity.'),
    assumptions: [BI('الشهر الناقص لا يدخل نقطة بيانات أبدًا؛ وإذا قلّت الأشهر المكتملة في السنة تُستكمل النافذة من نهاية العام السابق.', 'A partial month is never a data point; in a young year the previous year’s last months complete the window.')] },
  forecastBaseline: { filters: filt('العام المالي + الأمانة / الجهة المختارة (يُحسب من أشهرها المكتملة).', 'Fiscal year + the selected Amanah / entity (computed from its own complete months).'),
    assumptions: [BI('المنهج runrate3_v2: متوسط التحصيل الشهري لآخر 3 أشهر مكتملة يستمر بلا تغيير حتى 31 ديسمبر؛ النافذة تُكتب بجانب الرقم.', 'Method runrate3_v2: the average monthly receipts of the last 3 complete months continues unchanged to 31 December; the window is printed beside the figure.'),
      BI('المتبقي من الشهر الحالي يُحتسب بالتناسب على أيام الشهر؛ الشهر الحالي غير المكتمل ليس نقطة بيانات في الأساس.', 'The rest of the current month is prorated by calendar days; the incomplete current month is not a data point of the baseline.'),
      BI('لا موسمية، ولا استرداد لأرصدة متأخرة، ولا أثر لأي إجراء تحصيل مفترض.', 'No seasonality, no recovery of overdue balances, and no benefit credited to any collection action.'),
      BI('المحصّل بتاريخ الدفع على كل الفواتير، والمستهدف لا يدخل في الحساب.', 'Receipts by payment date on any invoice; the target is not an input of the estimate.'),
      BI('خط أساس توضيحي وليس نموذجًا معتمدًا ولا نطاق ثقة له، وغير مُواءَم مع منهجية فرق التوقع — قيد التنسيق.', 'An illustrative baseline, not an approved model, with no confidence range, and not aligned with the forecasting teams’ methodology — coordination pending.')] },
  forecastAchievement: { filters: filt('الخطة المختارة + عرض الأمانة / البلدية.', 'The selected plan + the Amanah / municipality view.'),
    assumptions: [BI('نسبة المتوقع إلى المستهدف مقياس تحقق متوقع وليست احتمالية؛ لا تُلوَّن بلون ثقة.', 'The expected-to-target ratio is an expected-achievement measure and not a probability; it carries no confidence colour.')],
    moreNotes: [BI('الفرق بين المقياسين: «نسبة تحقيق المستهدف المتوقعة بنهاية الفترة» = المتوقع ÷ المستهدف (حساب محدد من خط الأساس)، أما «الاحتمالية» فغير مقدَّرة لقلة السجل.', 'The difference between the two: «expected target achievement by the end of the period» = expected ÷ target (a defined calculation from the baseline), while the «probability» is not estimated because the record is too short.')] },
  forecastGap: { filters: filt('العام المالي + الأمانة / الجهة المختارة.', 'Fiscal year + the selected Amanah / entity.'), assumptions: [BI('الفجوة تتبع افتراضات خط الأساس والخطة المتساوية؛ وليست تقديرًا معتمدًا.', 'The gap follows the baseline’s assumptions and the even plan; it is not an approved estimate.')] },
  gapContribution: { filters: BI('العام المالي؛ أشرطة الجهات على كل الجهات المتاحة مع تمييز الجهة المختارة. لا مساهمة لمصدر الإيراد. ' + F_ACCESS.ar, 'Fiscal year; the entity bars run over every available entity with the selected one marked. No contribution by revenue source. ' + F_ACCESS.en),
    assumptions: [BI('المساهمة على مستوى الجهة فقط لأن المستهدف معرّف للجهة لا للمصدر.', 'Contribution is at entity level only because the target is defined for the entity, not the source.')],
    moreNotes: [BI('صف «أخرى» في الأشرطة يضم الجهات غير المعروضة والإيرادات المحصلة غير المنسوبة إلى جهة، فيتطابق مجموع الأشرطة مع الانحراف الكلي.', 'The «Other» bar holds the entities not drawn and the receipts not attributed to an entity, so the bars add up to the total deviation.')] },
  actionClasses: { filters: BI('الأمانة / الجهة؛ السنة الجارية فقط لأن الأسطر تصف الرصيد القائم اليوم؛ اختيار مصدر الإيراد في الرسم يضيّق الجدول؛ نطاق البلديات المحدد يجمّع حسب البلدية. يحتاج وحدة «التخطيط»، وفتح السجلات يحتاج وحدة «الفواتير غير المحصّلة».', 'Amanah / entity; the current year only because the lines describe today’s standing balance; choosing a revenue source in the chart narrows the table; a municipal access scope groups by municipality. It needs the «Planning» module, and opening the records needs the «Uncollected invoices» module.'),
    assumptions: [BI('حدّ 180 يومًا وانتماء الإجراءات القائمة إلى الفئة A توصية قرار D-10 تنتظر تأكيد مسؤولي التحصيل.', 'The 180-day line and class A’s membership are the D-10 recommendation, pending the collection owners.'), BI('الأثر المتوقع للإجراء «غير متاح»: لا تقدير للاسترداد.', 'The expected impact of an action is «not available»: no recovery estimate.')],
    moreNotes: [BI('المبلغ القابل للمتابعة = الفئة B (متأخر حتى 180 يومًا) + الفئة C (يستحق حتى 31 ديسمبر). المحجوب (A) والأقدم من 180 يومًا (D) مجموعتان منفصلتان لا تدخلان فيه، والمستحق بعد نهاية السنة (E) وغير المتاح تاريخه (U) خارجه.', 'Actionable amount = class B (overdue up to 180 days) + class C (falls due by 31 December). Blocked (A) and older than 180 days (D) are separate groups outside it, as are due-after-year-end (E) and due-date-unavailable (U).'), BI('كل فاتورة في سطر واحد بالأسبقية: عائق ثم تاريخ استحقاق غير متاح ثم أقدم من 180 يومًا ثم متأخر ثم يستحق قبل نهاية السنة ثم بعدها.', 'Each invoice sits in one line by precedence: blocker, then due date unavailable, then older than 180 days, then overdue, then due by year end, then after.')] },
  planVsPlan: { filters: filt('الخطة المختارة + عرض الأمانة / البلدية.', 'The selected plan + the Amanah / municipality view.'), assumptions: [BI('المقام المخطط حتى تاريخه بالتوزيع الشهري الصريح للخطة.', 'The denominator is planned to date by the plan\'s explicit monthly distribution.')] },
  planConcepts: { filters: BI('اختيار الخطة من «خطط الإيرادات»؛ عرض الأمانة / البلدية لا يكتب الخطة.', 'The plan is chosen from «Revenue plans»; the Amanah / municipality view never writes the plan.'), assumptions: [BI('اسم الخطة فريد ومالكها منشئها ولا يتغير؛ وخطة كل مستخدم الافتراضية لا تغيّر الخطة المرجعية للتقارير.', 'A plan name is unique and its owner is its creator and never changes; a user\'s default plan does not change the reference plan for reports.')] },
  planDates: { filters: BI('الخطة المختارة + عرض الأمانة / البلدية.', 'The selected plan + the Amanah / municipality view.'), assumptions: [] },
  forecastAlignment: { filters: filt('الخطة المختارة + عرض الأمانة / البلدية.', 'The selected plan + the Amanah / municipality view.'), assumptions: [BI('خط أساس توضيحي (وتيرة حديثة) وليس نموذجًا ولا نطاق ثقة له.', 'An illustrative baseline (a recent run-rate), not a model, and with no confidence range.')] },
  equalDistribution: { filters: filt('الخطة المختارة.', 'The selected plan.'), assumptions: [BI('افتراض صريح بانتظار توزيع شهري مؤكد من الإدارة المالية.', 'An explicit assumption pending a monthly distribution confirmed by Finance.')] },
  probabilityStatus: { filters: BI('لا تصفية تغيّر الحالة: غير مقدَّرة لكل نطاق وسنة.', 'No filter changes the state: not estimated for every scope and year.'),
    assumptions: [BI('لا تُعرض احتمالية قبل توفر سجل يمكن التحقق منه؛ ولا تُستعمل نسبة التوقع إلى المستهدف بديلًا.', 'No probability is shown until a verifiable record exists; the forecast ÷ target ratio is never used instead.')],
    moreNotes: [BI('الحالة على الصفحة: الرسالة «لا تتوفر بيانات كافية لتقدير احتمالية موثوقة» وسببها، بجانب التوقع بنهاية السنة (المبلغ والنسبة والفجوة).', 'On the page: the message «not enough data to estimate a reliable probability» with its reason, beside the year-end forecast (amount, ratio and gap).')] }
};
export const PLANNING_METRICS = BASE.map((m) => { const x = EXTRA[m.key] || {}; return { ...m, filters: x.filters || null, assumptions: x.assumptions || [], notes: [...(m.notes || []), ...(x.moreNotes || [])] }; });

/** a row of dictionaryDocs.js FORMULA_GROUPS (same structure, plus the full set of definition fields) */
export const planningFormulaRows = () => PLANNING_METRICS.map((m) => ({
  name: m.label, f: m.f, meaning: m.brief, where: m.where,
  unit: m.unit, level: m.level, dateBasis: m.dateBasis, sourceFields: m.sourceFields, missing: m.missing, owner: m.owner, filters: m.filters, assumptions: m.assumptions
}));
